from collections import defaultdict

def can_chain(dominoes):
    if not dominoes:
        return True

    deg = defaultdict(int)
    adj = defaultdict(list)

    for a, b in dominoes:
        # degree: loops contribute 2, non-loops contribute 1 to each endpoint
        deg[a] += 1
        deg[b] += 1
        # adjacency for connectivity check (add both directions)
        adj[a].append(b)
        adj[b].append(a)

    # all vertices in a Eulerian circuit must have even degree
    for v in deg:
        if deg[v] % 2 != 0:
            return False

    # find a start vertex with degree > 0
    start = next((v for v, d in deg.items() if d > 0), None)
    if start is None:
        return True

    # DFS to check connectivity among vertices with degree > 0
    visited = set()
    stack = [start]
    while stack:
        v = stack.pop()
        if v in visited:
            continue
        visited.add(v)
        for nb in adj[v]:
            if nb not in visited:
                stack.append(nb)

    for v, d in deg.items():
        if d > 0 and v not in visited:
            return False

    return True
